// Washer PIN login. Needs n8n env NODE_FUNCTION_ALLOW_BUILTIN=crypto and FIREBASE_SA_JSON (the service account
// key, set on the server only). Never paste a key into this node, and never log the request: it carries a PIN.
const crypto = require('crypto');
// Washer PIN login: pure helpers. The workflow's Code node embeds this file (plus logic.js) after
// `const crypto = require('crypto')`, and test.mjs runs the same text against Node's crypto.
// Nothing here talks to the network and nothing here logs: a PIN, a hash or a key never leaves a function.

const PIN_ITER = 150000;        // PBKDF2-SHA256 iterations (the admin page uses the same number)
const PIN_KEYLEN = 32;          // bytes
const PIN_MAX_FAILS = 5;        // wrong PINs in a row before the lock
const PIN_LOCK_MS = 15 * 60 * 1000;
const FCM_AUD = 'https://identitytoolkit.googleapis.com/google.identity.identitytoolkit.v1.IdentityToolkit';
const OAUTH_URL = 'https://oauth2.googleapis.com/token';
const OAUTH_SCOPES = [
  'https://www.googleapis.com/auth/datastore',
  'https://www.googleapis.com/auth/identitytoolkit',
  'https://www.googleapis.com/auth/cloud-platform',
].join(' ');
// Numbers that may never sign in with a PIN, whatever Firestore says: the admins (their phone number is what
// makes them admin in the rules, so a PIN for them would be a PIN for the whole database).
const PIN_DENY = ['+917701808924'];

// '9876504210' (exactly 10 digits, Indian mobile) -> '+919876504210', anything else -> null
function pinPhone(v) {
  const s = typeof v === 'string' || typeof v === 'number' ? String(v).trim() : '';
  return /^[6-9]\d{9}$/.test(s) ? '+91' + s : null;
}
const pinOk = v => typeof v === 'string' && /^\d{4,6}$/.test(v);

function b64url(buf) {
  return Buffer.from(buf).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
}

// PBKDF2-SHA256(pin, salt) -> base64. salt is base64 (16 random bytes from the admin page).
function pinHash(pin, saltB64) {
  return crypto.pbkdf2Sync(Buffer.from(String(pin), 'utf8'), Buffer.from(String(saltB64), 'base64'), PIN_ITER, PIN_KEYLEN, 'sha256').toString('base64');
}

// Constant-time check. Always runs the full PBKDF2, even when the stored record is malformed.
function pinVerify(pin, rec) {
  const salt = rec && typeof rec.salt === 'string' ? rec.salt : '';
  const want = Buffer.from(rec && typeof rec.hash === 'string' ? rec.hash : '', 'base64');
  const got = Buffer.from(pinHash(pin, salt || 'AAAAAAAAAAAAAAAAAAAAAA=='), 'base64');
  const shapeOk = salt.length > 0 && want.length === PIN_KEYLEN;
  const cmp = shapeOk ? want : Buffer.alloc(PIN_KEYLEN);
  const same = crypto.timingSafeEqual(got, cmp);
  return shapeOk && same;
}

// Is this record locked at `now` (ms)? Returns the unlock time in ms, or 0.
function pinLockedUntil(rec, now) {
  const t = rec && rec.locked_until ? Date.parse(rec.locked_until) : NaN;
  return Number.isFinite(t) && t > now ? t : 0;
}

// Counters after a wrong PIN. The 5th wrong one in a row locks for 15 minutes and starts the count again.
function pinAfterFail(rec, now) {
  const before = rec && Number.isInteger(rec.fails) && rec.fails > 0 ? rec.fails : 0;
  const fails = before + 1;
  if (fails >= PIN_MAX_FAILS) return { fails: 0, locked_until: new Date(now + PIN_LOCK_MS).toISOString(), locked: true };
  return { fails, locked_until: null, locked: false };
}

/* ---------- service account + JWTs (RS256) ---------- */
// FIREBASE_SA_JSON may be the key JSON itself or the same JSON base64-encoded (one safe line for an env file).
function parseSa(raw) {
  let sa = raw;
  if (typeof raw === 'string') {
    let txt = raw.trim();
    if (txt && txt[0] !== '{') { try { txt = Buffer.from(txt, 'base64').toString('utf8') } catch (e) { return null } }
    try { sa = JSON.parse(txt) } catch (e) { return null }
  }
  if (!sa || typeof sa !== 'object') return null;
  if (typeof sa.client_email !== 'string' || !/@.+\.iam\.gserviceaccount\.com$/.test(sa.client_email)) return null;
  if (typeof sa.private_key !== 'string' || sa.private_key.indexOf('PRIVATE KEY') < 0) return null;
  if (typeof sa.project_id !== 'string' || !/^[a-z0-9-]{4,40}$/.test(sa.project_id)) return null;
  return { client_email: sa.client_email, private_key: sa.private_key, project_id: sa.project_id };
}

function signJwt(payload, pem) {
  const head = b64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const body = b64url(JSON.stringify(payload));
  const s = crypto.createSign('RSA-SHA256');
  s.update(head + '.' + body);
  return head + '.' + body + '.' + b64url(s.sign(pem));
}

// The grant Google's token endpoint swaps for an access token (1 hour).
function oauthAssertion(sa, nowMs) {
  const iat = Math.floor(nowMs / 1000);
  return signJwt({ iss: sa.client_email, sub: sa.client_email, scope: OAUTH_SCOPES, aud: OAUTH_URL, iat, exp: iat + 3600 }, sa.private_key);
}

// A Firebase custom token for `uid`: the app passes it to signInWithCustomToken. Valid for at most an hour.
function customToken(sa, uid, nowMs) {
  if (typeof uid !== 'string' || !uid || uid.length > 128) throw new Error('bad uid');
  const iat = Math.floor(nowMs / 1000);
  return signJwt({ iss: sa.client_email, sub: sa.client_email, aud: FCM_AUD, iat, exp: iat + 3600, uid }, sa.private_key);
}

/* ---------- Firestore REST values ---------- */
function fsValue(v) {
  if (!v || typeof v !== 'object') return undefined;
  if ('stringValue' in v) return v.stringValue;
  if ('integerValue' in v) return Number(v.integerValue);
  if ('doubleValue' in v) return Number(v.doubleValue);
  if ('booleanValue' in v) return v.booleanValue;
  if ('nullValue' in v) return null;
  if ('timestampValue' in v) return v.timestampValue;
  return undefined;     // maps/arrays are not needed here
}
function fsFields(doc) {
  const out = {}, f = doc && doc.fields && typeof doc.fields === 'object' ? doc.fields : {};
  for (const k of Object.keys(f)) out[k] = fsValue(f[k]);
  return out;
}
function fsEncode(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === 'boolean') return { booleanValue: v };
  if (Number.isInteger(v)) return { integerValue: String(v) };
  if (typeof v === 'number') return { doubleValue: v };
  return { stringValue: String(v) };
}

// Washer PIN login: the whole request, start to finish. deps carries everything that touches the outside:
//   saRaw    the service account JSON (n8n env FIREBASE_SA_JSON)
//   project  optional n8n env FIREBASE_PROJECT_ID; must match the key's project when set
//   deny     optional extra numbers that may never use a PIN (n8n env PIN_DENY_PHONES, comma separated)
//   http({method,url,headers,body}) -> {status, body}   never throws; status 0 = no answer
//   now() -> ms, sleep(ms), jitter() -> ms of extra delay on a failure
// Returns { status, body } for the Respond node. body is { ok:true, token } or { ok:false, code } with code one of
// bad_pin | locked | not_set | not_washer | server, and nothing else, whatever went wrong.

async function pinLogin(reqBody, deps) {
  const fail = async code => {
    try { await deps.sleep(400 + Math.max(0, Math.min(600, Number(deps.jitter()) || 0))) } catch (e) { }
    return { status: code === 'server' ? 500 : 200, body: { ok: false, code } };
  };
  try {
    const b = reqBody && typeof reqBody === 'object' ? reqBody : {};
    const phone = pinPhone(b.phone);
    const pin = b.pin;
    if (!phone || !pinOk(pin)) return await fail('bad_pin');

    const sa = parseSa(deps.saRaw);
    if (!sa) return await fail('server');
    const project = String(deps.project || '').trim();
    if (project && project !== sa.project_id) return await fail('server');
    const deny = PIN_DENY.concat(String(deps.deny || '').split(',').map(s => s.trim()).filter(Boolean));
    if (deny.indexOf(phone) >= 0) return await fail('not_washer');

    // Google access token for Firestore + Identity Toolkit (asked fresh for every login: logins are rare)
    const tok = await deps.http({
      method: 'POST', url: OAUTH_URL,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: 'grant_type=' + encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer') + '&assertion=' + encodeURIComponent(oauthAssertion(sa, deps.now())),
    });
    const access = tok.status === 200 && tok.body && typeof tok.body.access_token === 'string' ? tok.body.access_token : '';
    if (!access) return await fail('server');
    const auth = { Authorization: 'Bearer ' + access };
    const docs = 'https://firestore.googleapis.com/v1/projects/' + sa.project_id + '/databases/(default)/documents/';
    const pinUrl = docs + 'washerpins/' + encodeURIComponent(phone);
    const getDoc = async url => {
      const r = await deps.http({ method: 'GET', url, headers: auth });
      if (r.status === 404) return { missing: true };
      if (r.status !== 200 || !r.body || typeof r.body !== 'object') return null;
      return { fields: fsFields(r.body), updateTime: r.body.updateTime };
    };
    // write only `fields`, and only if nobody else wrote the doc since we read it (two logins at once must not
    // both count from the same `fails`). 'ok' | 'conflict' | 'error'
    const patch = async (fields, updateTime) => {
      const keys = Object.keys(fields);
      const q = keys.map(k => 'updateMask.fieldPaths=' + encodeURIComponent(k)).join('&')
        + '&currentDocument.updateTime=' + encodeURIComponent(updateTime);
      const enc = {}; keys.forEach(k => { enc[k] = fsEncode(fields[k]) });
      const r = await deps.http({ method: 'PATCH', url: pinUrl + '?' + q, headers: { ...auth, 'Content-Type': 'application/json' }, body: JSON.stringify({ fields: enc }) });
      if (r.status === 200) return 'ok';
      const st = r.body && r.body.error && r.body.error.status;
      if (r.status === 409 || st === 'FAILED_PRECONDITION' || st === 'ABORTED') return 'conflict';
      return 'error';
    };

    let passed = false;
    for (let round = 0; round < 3 && !passed; round++) {
      const d = await getDoc(pinUrl);
      if (!d) return await fail('server');
      const rec = d.fields || {};
      if (d.missing || rec.active !== true || typeof rec.hash !== 'string' || typeof rec.salt !== 'string') return await fail('not_set');
      if (typeof d.updateTime !== 'string' || !d.updateTime) return await fail('server');
      const now = deps.now();
      if (pinLockedUntil(rec, now)) return await fail('locked');
      if (!pinVerify(pin, rec)) {
        const nx = pinAfterFail(rec, now);
        const w = await patch({ fails: nx.fails, locked_until: nx.locked_until }, d.updateTime);
        if (w === 'conflict') continue;           // someone else tried at the same moment: count again from fresh
        if (w !== 'ok') return await fail('server'); // never answer "wrong PIN" without having counted it
        return await fail(nx.locked ? 'locked' : 'bad_pin');
      }
      // right PIN: only now is it worth saying whether this number may work at all
      const wd = await getDoc(docs + 'washers/' + encodeURIComponent(phone));
      if (!wd) return await fail('server');
      if (wd.missing || !wd.fields || wd.fields.status !== 'approved') return await fail('not_washer');
      if ((rec.fails || 0) !== 0 || rec.locked_until) {
        const w = await patch({ fails: 0, locked_until: null }, d.updateTime);
        if (w === 'conflict') continue;
        if (w !== 'ok') return await fail('server');
      }
      passed = true;
    }
    if (!passed) return await fail('server');

    // the Firebase user for this number: the same uid the phone-OTP sign-in made, so rules and data carry over
    const it = 'https://identitytoolkit.googleapis.com/v1/projects/' + sa.project_id;
    const json = { ...auth, 'Content-Type': 'application/json' };
    const lookup = async () => {
      const r = await deps.http({ method: 'POST', url: it + '/accounts:lookup', headers: json, body: JSON.stringify({ phoneNumber: [phone] }) });
      if (r.status !== 200 || !r.body || typeof r.body !== 'object') return null;
      const users = Array.isArray(r.body.users) ? r.body.users.filter(u => u && u.phoneNumber === phone) : [];
      return { user: users[0] || null };
    };
    let found = await lookup();
    if (!found) return await fail('server');
    let user = found.user;
    if (!user) {
      const r = await deps.http({ method: 'POST', url: it + '/accounts', headers: json, body: JSON.stringify({ phoneNumber: phone }) });
      if (r.status === 200 && r.body && typeof r.body.localId === 'string') user = { localId: r.body.localId, phoneNumber: phone };
      else {
        found = await lookup();            // made at the same moment by another login
        user = found && found.user;
      }
      if (!user) return await fail('server');
    }
    if (user.disabled === true) return await fail('not_washer');
    if (typeof user.localId !== 'string' || !user.localId) return await fail('server');
    return { status: 200, body: { ok: true, token: customToken(sa, user.localId, deps.now()) } };
  } catch (e) {
    return await fail('server');
  }
}

const helpers = this.helpers;
const http = async o => {
  try {
    const r = await helpers.httpRequest({ method: o.method, url: o.url, headers: o.headers, body: o.body,
      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 10000 });
    let b = r && r.body;
    if (Buffer.isBuffer(b)) b = b.toString('utf8');
    if (typeof b === 'string') { try { b = JSON.parse(b) } catch (e) { b = null } }
    return { status: Number(r && r.statusCode) || 0, body: b };
  } catch (e) { return { status: 0, body: null } }
};
const out = await pinLogin($input.first().json.body, {
  saRaw: $env.FIREBASE_SA_JSON, project: $env.FIREBASE_PROJECT_ID, deny: $env.PIN_DENY_PHONES,
  http, now: () => Date.now(), jitter: () => crypto.randomInt(0, 400),
  sleep: ms => new Promise(r => (typeof setTimeout === 'function' ? setTimeout(r, ms) : r())),
});
return [{ json: out }];
